SQL_DOC.P_SQL:
DECLARE V_CNT NUMBER; BEGIN
SELECT COUNT(*) AS CNT INTO V_CNT FROM KEPETIF01 WHERE CSTMR_BIZMN_REGST_NO = NVL($V_CSTMR_BIZMN_REGST_NO$,'-') AND SPPLR_BIZMN_REGST_NO = NVL($V_SPPLR_BIZMN_REGST_NO$,'-') AND DEPT_CD = NVL($V_DEPT_CD$,'-') AND AMT_LIMT_CD = NVL($V_AMT_LIMT_CD$,'-') AND PAY_CND_CD = NVL($V_PAY_CND_CD$,'-') AND PAY_FORM_CD = NVL($V_PAY_FORM_CD$,'-') AND CLSN_STRT_DAY = NVL($V_CLSN_STRT_DAY$,'-') AND CLSN_FNSH_DAY = NVL($V_CLSN_FNSH_DAY$,'-') AND USE_STRT_DATE = NVL($V_USE_STRT_DATE$,'-') AND USE_FNSH_DATE = NVL($V_USE_FNSH_DATE$,'-') AND ALANC_TYP_CD = NVL($V_ALANC_TYP_CD$,'-') ;
IF V_CNT = 0 THEN INSERT INTO KEPETIF01 ( CSTMR_BIZMN_REGST_NO, SPPLR_BIZMN_REGST_NO, DEPT_CD, AMT_LIMT_CD, PAY_CND_CD, PAY_FORM_CD, CLSN_STRT_DAY, CLSN_FNSH_DAY, USE_STRT_DATE, USE_FNSH_DATE, ALANC_TYP_CD, SITE_NM, CSTMR_NM, SPPLR_NM, DEPT_NM ) VALUES ( NVL($V_CSTMR_BIZMN_REGST_NO$,'-'), NVL(TRIM($V_SPPLR_BIZMN_REGST_NO$),'-'), NVL($V_DEPT_CD$,'-'), NVL($V_AMT_LIMT_CD$,'-'), NVL($V_PAY_CND_CD$,'-'), NVL($V_PAY_FORM_CD$,'-'), NVL($V_CLSN_STRT_DAY$,'-'), NVL($V_CLSN_FNSH_DAY$,'-'), NVL($V_USE_STRT_DATE$,'-'), NVL($V_USE_FNSH_DATE$,'-'), NVL($V_ALANC_TYP_CD$,'-'), NVL($V_SITE_NM$,'-'), NVL($V_CSTMR_NM$,'-'), NVL($V_SPPLR_NM$,'-'), NVL($V_DEPT_NM$,'-') ); ELSE UPDATE KEPETIF01 SET SITE_NM = NVL($V_SITE_NM$,'-'), CSTMR_NM = NVL($V_CSTMR_NM$,'-'), SPPLR_NM = NVL($V_SPPLR_NM$,'-'), DEPT_NM = NVL($V_DEPT_NM$,'-') WHERE CSTMR_BIZMN_REGST_NO = NVL($V_CSTMR_BIZMN_REGST_NO$,'-') AND SPPLR_BIZMN_REGST_NO = NVL($V_SPPLR_BIZMN_REGST_NO$,'-') AND DEPT_CD = NVL($V_DEPT_CD$,'-') AND AMT_LIMT_CD = NVL($V_AMT_LIMT_CD$,'-') AND PAY_CND_CD = NVL($V_PAY_CND_CD$,'-') AND PAY_FORM_CD = NVL($V_PAY_FORM_CD$,'-') AND CLSN_STRT_DAY = NVL($V_CLSN_STRT_DAY$,'-') AND CLSN_FNSH_DAY = NVL($V_CLSN_FNSH_DAY$,'-') AND USE_STRT_DATE = NVL($V_USE_STRT_DATE$,'-') AND USE_FNSH_DATE = NVL($V_USE_FNSH_DATE$,'-') AND ALANC_TYP_CD = NVL($V_ALANC_TYP_CD$,'-'); END IF;
END;
